INSERT INTO public.blitz_questions(topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) VALUES
('Обращения граждан — оформление','В администрацию поступило бумажное заявление без личной подписи. Какое требование к письменному обращению не выполнено?','["Обязательная нотариальная форма","Обязательная подпись гражданина и дата","Обязательное согласование с депутатом","Обязательная регистрация на Госуслугах"]'::jsonb,1,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_59999/c75556cf6fc05793e3c6315a7101fb59e6af9b02/','Статья 7 предусматривает подпись и дату письменного обращения.',true),
('Обращения граждан — оформление','Гражданин направляет письменную жалобу по почте. Какой адрес должен быть указан для получения ответа?','["Почтовый адрес, по которому направляют ответ и уведомление","Только адрес электронной почты","Адрес любого соседнего государственного органа","Адрес регистрации юридического лица, даже если его нет"]'::jsonb,0,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_59999/c75556cf6fc05793e3c6315a7101fb59e6af9b02/','В бумажном обращении гражданин указывает почтовый адрес для ответа.',true),
('Обращения граждан — оформление','Заявитель направил электронное обращение через идентифицированный личный кабинет ведомства. Достаточно ли уникального идентификатора кабинета для ответа вместо почтового адреса?','["Нет, электронные обращения запрещены","Нет, всегда нужен только бумажный адрес","Да, даже если отправитель не идентифицирован и канал не предусмотрен законом","Да, если используется предусмотренная законом идентифицирующая система"]'::jsonb,3,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_59999/c75556cf6fc05793e3c6315a7101fb59e6af9b02/','Статья 7 допускает адрес/идентификатор кабинета в соответствующей информационной системе.',true),
('Обращения граждан — оформление','Нужно ли гражданину обязательно прикладывать подтверждающие документы к каждому письменному обращению?','["Да, не менее трёх приложений","Да, только нотариальные оригиналы","Нет, документы прилагаются при необходимости","Да, только при обращении к муниципалитету"]'::jsonb,2,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_59999/c75556cf6fc05793e3c6315a7101fb59e6af9b02/','Приложение документов допускается при необходимости, но не является универсальным обязательным требованием.',true),
('Обращения граждан — компетенция','Канцелярия получила обращение в понедельник. Какой срок установлен для его обязательной регистрации?','["В течение семи рабочих дней","В течение трёх дней с момента поступления","До окончания календарного месяца","Непосредственно за 30 дней до рассмотрения"]'::jsonb,1,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_59999/0c7123ee40ad90f89afa6fa544a87ffe76c084c0/','Часть 2 статьи 8 предписывает регистрацию в течение трёх дней.',true),
('Обращения граждан — компетенция','В областной орган пришло обращение, целиком находящееся в компетенции федерального ведомства. Каков общий срок переадресации после регистрации?','["Семь дней со дня регистрации с уведомлением гражданина","Тридцать дней с даты подписания письма","Семьдесят два часа со дня публикации на сайте","После окончания очередного бюджетного года"]'::jsonb,0,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_59999/0c7123ee40ad90f89afa6fa544a87ffe76c084c0/','Часть 3 статьи 8 предусматривает направление по компетенции в течение семи дней.',true),
('Обращения граждан — компетенция','В жалобе гражданин обжалует решение конкретного ведомства. Можно ли направить жалобу на рассмотрение этому же ведомству?','["Да, это единственный допустимый вариант","Да, если обращение получено по электронной почте","Да, если жалоба подписана в бумажной форме","Нет, направление тому, чьи действия обжалуются, запрещено"]'::jsonb,3,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_59999/0c7123ee40ad90f89afa6fa544a87ffe76c084c0/','Часть 6 статьи 8 прямо запрещает такое направление.',true),
('Обращения граждан — компетенция','Жалоба не может быть передана по компетенции из-за запрета направлять её объекту обжалования. Что предписывает закон?','["Немедленно уничтожить материалы без уведомления","Направить жалобу тому же адресату повторно","Вернуть с разъяснением права судебного обжалования","Оставить заявление без движения на три года"]'::jsonb,2,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_59999/0c7123ee40ad90f89afa6fa544a87ffe76c084c0/','Часть 7 статьи 8 требует вернуть жалобу и разъяснить судебный порядок обжалования.',true),
('Обращения граждан — компетенция','Обращение касается полномочий одновременно трёх органов власти. Что должен сделать зарегистрировавший его орган?','["Отказать из-за множественности компетенций","Направить копии обращения компетентным органам в течение семи дней","Назначить один орган без передачи материалов","Ожидать, пока заявитель сам подаст три новых обращения"]'::jsonb,1,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_59999/0c7123ee40ad90f89afa6fa544a87ffe76c084c0/','Часть 4 статьи 8 предусматривает рассылку копий обращения компетентным органам.',true),
('Обращения граждан — компетенция','В обращении содержатся сведения о возможных нарушениях законодательства о миграции. Какой специальный срок переадресации установлен частью 3.1 статьи 8?','["Пять дней со дня регистрации","Десять календарных дней","Один месяц после рассмотрения","Двадцать рабочих дней"]'::jsonb,0,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_59999/0c7123ee40ad90f89afa6fa544a87ffe76c084c0/','Специальный пятидневный срок применяется к сообщениям о возможных нарушениях в сфере миграции.',true),
('Обращения граждан — компетенция','Куда по специальному правилу направляют обращение о возможных нарушениях миграционного законодательства?','["Только в финансовый орган региона","Только в Конституционный Суд","В муниципальную избирательную комиссию","В территориальный орган МВД и высшему должностному лицу субъекта РФ"]'::jsonb,3,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_59999/0c7123ee40ad90f89afa6fa544a87ffe76c084c0/','Часть 3.1 статьи 8 определяет двух адресатов такой переадресации.',true),
('Обращения граждан — рассмотрение','Компетентное ведомство отказывается рассматривать поступившее по компетенции обращение, ссылаясь на отсутствие интереса. Соответствует ли это статье 9?','["Да, ведомство вправе отклонить его без основания","Да, но только после отправки гражданину рекламного сообщения","Нет, такое обращение подлежит обязательному рассмотрению","Да, если заявитель не является служащим"]'::jsonb,2,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 9','https://www.consultant.ru/document/cons_doc_LAW_59999/cf9a19c94147d592f8fbcc129fe2d83d8102e5fa/','Часть 1 статьи 9 закрепляет обязательность рассмотрения обращения по компетенции.',true),
('Обращения граждан — рассмотрение','Допустимо ли для проверки изложенных фактов обеспечить рассмотрение обращения с выездом на место?','["Нет, выезд запрещён законом","Да, при необходимости","Только после федерального референдума","Только при изменении границ субъекта"]'::jsonb,1,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 9','https://www.consultant.ru/document/cons_doc_LAW_59999/cf9a19c94147d592f8fbcc129fe2d83d8102e5fa/','Часть 2 статьи 9 разрешает выездное рассмотрение при необходимости.',true),
('Обращения граждан — рассмотрение','По обращению необходимо запросить документы у другого компетентного органа. Каков общий срок предоставления им материалов по надлежащему запросу?','["Пятнадцать дней","Три месяца","Пять рабочих дней во всех случаях","Один календарный год"]'::jsonb,0,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_59999/ca24c3b3a2032a1f727146f988f406723bf9ea1a/','Часть 2 статьи 10 устанавливает пятнадцатидневный срок с исключениями для охраняемой законом тайны.',true),
('Обращения граждан — рассмотрение','Кто вправе подписывать официальный ответ на обращение по статье 10?','["Только любое физическое лицо, не связанное с органом","Исключительно избирательная комиссия","Только нотариус по поручению заявителя","Руководитель органа, должностное или уполномоченное лицо"]'::jsonb,3,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_59999/ca24c3b3a2032a1f727146f988f406723bf9ea1a/','Часть 3 статьи 10 определяет возможных подписантов.',true),
('Обращения граждан — рассмотрение','Орган ограничился формальной отпиской, не рассмотрев заявленные обстоятельства. Какому требованию статьи 10 это противоречит?','["Требованию соблюдать партийную дисциплину","Обязанности обращаться в международный арбитраж","Объективному, всестороннему и своевременному рассмотрению","Правилу о предварительной оплате обращения"]'::jsonb,2,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_59999/ca24c3b3a2032a1f727146f988f406723bf9ea1a/','Пункт 1 части 1 статьи 10 обязывает объективно и всесторонне рассматривать обращение.',true),
('Обращения граждан — рассмотрение','Рассмотрение выявило нарушение прав заявителя. Что необходимо сделать помимо ответа по существу?','["Передать адрес заявителя сторонней компании","Принять меры по восстановлению или защите нарушенных прав","Ожидать нового обращения без действий","Объявить любое обращение анонимным"]'::jsonb,1,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_59999/ca24c3b3a2032a1f727146f988f406723bf9ea1a/','Пункт 3 части 1 статьи 10 предусматривает меры по восстановлению и защите прав.',true),
('Обращения граждан — рассмотрение','Электронное обращение поступило через идентифицированный кабинет гражданина. В каком порядке направляется ответ?','["Через соответствующий адрес или идентификатор кабинета","Только курьером с нотариальным удостоверением","Только через региональное телевидение","Лишь на адрес организации, не связанной с гражданином"]'::jsonb,0,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_59999/ca24c3b3a2032a1f727146f988f406723bf9ea1a/','Часть 4 статьи 10 предусматривает ответ по электронному адресу или идентификатору кабинета.',true),
('Обращения граждан — особые случаи','Гражданин подал жалобу непосредственно на судебное решение в административный орган. Что предписано статьёй 11?','["Самостоятельно отменить судебное решение","Передать жалобу в муниципальный финансовый орган","Назначить новое судебное разбирательство своим приказом","Вернуть в течение семи дней с разъяснением судебного порядка обжалования"]'::jsonb,3,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 11','https://www.consultant.ru/document/cons_doc_LAW_59999/1a1719408a99f43738c30a453a74ddaf6ccd7ae7/','Часть 2 статьи 11 предусматривает возврат обращения с разъяснением порядка обжалования.',true),
('Обращения граждан — особые случаи','В обращении содержатся угрозы жизни должностного лица. Какой вариант прямо допускает закон?','["В обязательном порядке опубликовать личные данные гражданина","Немедленно изменить границы муниципалитета","Оставить без ответа по существу и сообщить о недопустимости злоупотребления правом","Назначить заявителю дисциплинарное взыскание как служащему"]'::jsonb,2,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 11','https://www.consultant.ru/document/cons_doc_LAW_59999/1a1719408a99f43738c30a453a74ddaf6ccd7ae7/','Часть 3 статьи 11 предусматривает эту реакцию на угрозы и оскорбления.',true),
('Обращения граждан — особые случаи','Неразборчивое бумажное обращение содержит читаемые ФИО и почтовый адрес. Что должен предпринять орган?','["Считать его согласованием нового НПА","Сообщить в течение семи дней, что текст не поддаётся прочтению","Незамедлительно назначить уголовное наказание","Автоматически удовлетворить любые предполагаемые требования"]'::jsonb,1,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 11','https://www.consultant.ru/document/cons_doc_LAW_59999/1a1719408a99f43738c30a453a74ddaf6ccd7ae7/','Часть 4 статьи 11 устанавливает семидневное уведомление при читаемых сведениях об отправителе.',true),
('Обращения граждан — особые случаи','Гражданин неоднократно получает ответы на один и тот же вопрос и вновь пишет без новых обстоятельств. Возможно ли прекращение переписки по установленной процедуре?','["Да, при соблюдении условий части 5 статьи 11","Нет, необходимо ежегодно отвечать одинаково без исключений","Да, любое первое обращение можно считать повторным","Да, если оно направлено в иной орган без предыдущей переписки"]'::jsonb,0,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 11','https://www.consultant.ru/document/cons_doc_LAW_59999/1a1719408a99f43738c30a453a74ddaf6ccd7ae7/','Часть 5 статьи 11 допускает мотивированное прекращение переписки при установленных условиях.',true),
('Обращения граждан — гарантии','Ведомство хочет наказать гражданина за критику его действий в обращении. Как это оценивает 59-ФЗ?','["Допускается по усмотрению пресс-службы","Разрешено при письменной форме жалобы","Обязательно при критике руководства","Преследование гражданина за обращение запрещено"]'::jsonb,3,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_59999/5d404c7c015e7fd0ea194118470ec21d40d921ee/','Статья 6 запрещает преследование гражданина за обращение с критикой либо за защитой прав.',true),
('Обращения граждан — гарантии','Допустимо ли без согласия гражданина раскрыть сведения о его частной жизни из обращения?','["Да, сведения из любого обращения всегда публичны","Да, если их запросила коммерческая организация","Нет, в общем случае запрещено","Да, при размещении обращения в архиве органа"]'::jsonb,2,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_59999/5d404c7c015e7fd0ea194118470ec21d40d921ee/','Часть 2 статьи 6 защищает сведения обращения и частной жизни гражданина.',true),
('Обращения граждан — сроки','К губернатору поступило обращение о возможном нарушении миграционного законодательства. Каков специальный срок его рассмотрения?','["Один год с момента подачи","Двадцать дней со дня регистрации","Пять рабочих часов","Сорок пять дней без исключений"]'::jsonb,1,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 12','https://www.consultant.ru/document/cons_doc_LAW_59999/23fb391f3632e3f68a11e40c5a7711f3513cc674/','Часть 1.1 статьи 12 устанавливает особый двадцатидневный срок.',true),
('Обращения граждан — сроки','Кто может в исключительном случае продлить срок рассмотрения обычного обращения?','["Руководитель органа, должностное или уполномоченное лицо с уведомлением заявителя","Любой посетитель публичной приёмной","Любой подрядчик учреждения","Председатель частной организации без полномочий"]'::jsonb,0,'Федеральный закон от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»','статья 12','https://www.consultant.ru/document/cons_doc_LAW_59999/23fb391f3632e3f68a11e40c5a7711f3513cc674/','Часть 2 статьи 12 допускает продление не более чем на 30 дней с уведомлением.',true),
('Государственные услуги — права заявителя','Ведомство разместило устаревшие правила получения услуги и отказывается их обновлять. Какое право заявителя нарушено?','["На получение любой услуги без установленных условий","На отмену любых федеральных законов","На утверждение ведомственного бюджета","На полную, актуальную и достоверную информацию"]'::jsonb,3,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_103023/ec44362ff44a1158aa5b56cf5c77285e3c470b4e/','Статья 5 гарантирует доступ к полной, актуальной и достоверной информации.',true),
('Государственные услуги — права заявителя','Может ли заявитель требовать предоставления услуги в соответствии с её административным стандартом?','["Нет, стандарты имеют исключительно справочный характер","Только при устной договорённости с начальником","Да, своевременно и по установленному стандарту","Только по решению суда о назначении услуги"]'::jsonb,2,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_103023/ec44362ff44a1158aa5b56cf5c77285e3c470b4e/','Пункт 1 части 1 статьи 5 предусматривает своевременность и соблюдение стандарта.',true),
('Государственные услуги — права заявителя','Отдел запрещает электронное обращение, хотя закон не устанавливает такого запрета и способ предусмотрен. Какое право применяется?','["Право требовать автоматической выдачи любого разрешения","Выбор допустимой законом электронной формы получения услуги","Право установить для ведомства новый административный регламент","Право не представлять никаких обязательных документов"]'::jsonb,1,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_103023/ec44362ff44a1158aa5b56cf5c77285e3c470b4e/','Пункт 3 части 1 статьи 5 гарантирует электронную форму, если не запрещена законом.',true),
('Государственные услуги — права заявителя','Какой способ защиты доступен заявителю при нарушении порядка предоставления услуги наряду с судом?','["Досудебное (внесудебное) рассмотрение жалобы","Только заявление в иностранный парламент","Самостоятельная отмена решения через социальную сеть","Отказ от любых форм обжалования"]'::jsonb,0,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_103023/ec44362ff44a1158aa5b56cf5c77285e3c470b4e/','Пункт 4 части 1 статьи 5 закрепляет досудебное обжалование.',true),
('Государственные услуги — права заявителя','Можно ли получить услугу через МФЦ, когда действует соответствующее соглашение о взаимодействии?','["Нет, многофункциональные центры не предоставляют услуги","Только после отдельного федерального референдума","Только по приказу Центральной избирательной комиссии","Да, в соответствии с таким соглашением"]'::jsonb,3,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_103023/ec44362ff44a1158aa5b56cf5c77285e3c470b4e/','Пункт 5 части 1 статьи 5 допускает обращение в МФЦ по действующим соглашениям.',true),
('Государственные услуги — права заявителя','Заявитель просит, чтобы бумажный результат услуги в отношении ребёнка получил другой законный представитель, указанный им при подаче. Допускается ли это?','["Нет, это запрещено всегда","Да, без указания данных получателя и без проверки полномочий","Да, если соблюдены условия статьи 5 и заявитель не потребовал личного получения","Да, даже при письменном требовании получить лично"]'::jsonb,2,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_103023/ec44362ff44a1158aa5b56cf5c77285e3c470b4e/','Части 2–3 статьи 5 регулируют получение результата другим законным представителем.',true),
('Государственные услуги — обязанности органов','Орган предоставляет услугу вне утверждённого административного регламента. Правомерно ли такое отступление по усмотрению сотрудника?','["Да, сотрудник может произвольно менять порядок","Нет, услуга предоставляется по административному регламенту","Да, достаточно устного согласия коллег","Да, когда заявителей немного"]'::jsonb,1,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_103023/1ad52ab9177bbc53835519b62dbd061ddcc96223/','Пункт 1 части 1 статьи 6 закрепляет соблюдение административных регламентов.',true),
('Государственные услуги — обязанности органов','Соседнее ведомство направило предусмотренный законом межведомственный запрос документов. Как должен поступить орган-держатель сведений?','["Предоставить необходимые сведения безвозмездно с учётом исключений закона","Отказать, пока заявитель не заплатит лично","Направить запрос в частную организацию без ответа","Потребовать регистрацию нового юридического лица"]'::jsonb,0,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_103023/1ad52ab9177bbc53835519b62dbd061ddcc96223/','Пункт 3 части 1 статьи 6 устанавливает бесплатный межведомственный обмен.',true),
('Государственные услуги — обязанности органов','Орган предлагает выдавать все услуги только на бумаге, несмотря на предусмотренную законодательством электронную форму. Соответствует ли это 210-ФЗ?','["Да, цифровые услуги запрещены в государстве","Да, если ведомству так удобнее","Да, при отсутствии очередей","Нет, необходимо обеспечить законную электронную форму"]'::jsonb,3,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_103023/1ad52ab9177bbc53835519b62dbd061ddcc96223/','Пункт 2 части 1 статьи 6 предусматривает электронную форму, если не запрещена законом.',true),
('Государственные услуги — обязанности органов','Обязаны ли подведомственные организации отвечать на надлежащие межведомственные запросы необходимых сведений?','["Нет, обязанность есть только у физических лиц","Нет, всегда требуется судебное решение","Да, за установленными законом исключениями","Да, но только на возмездной основе"]'::jsonb,2,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_103023/1ad52ab9177bbc53835519b62dbd061ddcc96223/','Часть 2 статьи 6 предусматривает участие таких организаций в межведомственном обмене.',true),
('Государственные услуги — межведомственное взаимодействие','Заявитель принёс документы, но сотрудник потребовал сведения, уже находящиеся в государственном реестре и не подпадающие под исключения. Правомерно ли требование?','["Да, если сотруднику удобнее получить их лично","Нет, необходимые сведения запрашиваются межведомственно","Да, если учреждение находится в ином регионе","Да, когда посетитель записан через МФЦ"]'::jsonb,1,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_103023/a593eaab768d34bf2d7419322eac79481e73cf03/','Пункт 2 части 1 статьи 7 запрещает требовать имеющиеся у органов сведения с оговорёнными исключениями.',true),
('Государственные услуги — межведомственное взаимодействие','Может ли гражданин по своей инициативе представить документ, который орган обязан получить межведомственно?','["Да","Нет, любое добровольное представление запрещено","Только на основании решения прокуратуры","Только в оригинале без возможности копии"]'::jsonb,0,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_103023/a593eaab768d34bf2d7419322eac79481e73cf03/','Пункт 2 части 1 статьи 7 сохраняет право добровольно представить такие сведения.',true),
('Государственные услуги — межведомственное взаимодействие','Чиновник требует от заявителя согласования с другим ведомством, хотя такой шаг не входит в исключения закона. Как оценить требование?','["Оно обязательно при любой услуге","Оно законно при отсутствии платных услуг","Оно определяется исключительно желанием служащего","Оно запрещено частью 1 статьи 7"]'::jsonb,3,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_103023/a593eaab768d34bf2d7419322eac79481e73cf03/','Пункт 3 части 1 статьи 7 ограничивает перекладывание межведомственных согласований на заявителя.',true),
('Государственные услуги — межведомственное взаимодействие','После первого отказа ведомство без установленных исключений предъявило новое требование к документам, недостаток которых ранее не назывался. Законно ли это?','["Да, ведомство вправе добавлять требования бесконечно","Да, если подано электронное заявление","Нет, повторные новые требования в общем случае запрещены","Да, если отказ вынесен сотрудником МФЦ"]'::jsonb,2,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_103023/a593eaab768d34bf2d7419322eac79481e73cf03/','Пункт 4 части 1 статьи 7 препятствует необоснованному предъявлению новых требований после отказа.',true),
('Государственные услуги — межведомственное взаимодействие','После первоначального отказа изменились обязательные требования НПА. Допускается ли новое требование к комплекту документов?','["Нет, изменения закона всегда игнорируются","Да, при изменении нормативных требований","Да, лишь по решению частного подрядчика","Да, при любой устной просьбе ведомства"]'::jsonb,1,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_103023/a593eaab768d34bf2d7419322eac79481e73cf03/','Подпункт «а» пункта 4 части 1 статьи 7 предусматривает исключение при изменении НПА.',true),
('Государственные услуги — межведомственное взаимодействие','После первого отказа истёк срок действия документа заявителя. Может ли ведомство потребовать обновлённый документ?','["Да, это предусмотренное законом исключение","Нет, истечение срока действия всегда не имеет значения","Только если гражданин иностранный","Только с разрешения районного суда"]'::jsonb,0,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_103023/a593eaab768d34bf2d7419322eac79481e73cf03/','Подпункт «в» пункта 4 части 1 статьи 7 учитывает истечение срока действия документа.',true),
('Государственные услуги — межведомственное взаимодействие','При повторной подаче выявлена ошибка в документе, которого не было в предыдущем комплекте. Может ли орган потребовать исправление?','["Нет, можно требовать только прежние документы","Да, без объяснения причин и ссылок на нормы","Да, если заявитель не обратился через МФЦ","Да, если выполняются условия исключения части 1 статьи 7"]'::jsonb,3,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_103023/a593eaab768d34bf2d7419322eac79481e73cf03/','Подпункт «б» пункта 4 части 1 статьи 7 разрешает требование при новых ошибках в новых материалах.',true),
('Государственные услуги — межведомственное взаимодействие','Орган требует бумажный экземпляр документа, электронный образ которого уже удостоверен МФЦ по статье 16; специальные исключения отсутствуют. Правомерно ли?','["Да, всегда необходим бумажный оригинал","Да, если документ направлен вечером","Нет, повторное требование бумаги в общем случае запрещено","Да, независимо от НПА и способа заверения"]'::jsonb,2,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_103023/a593eaab768d34bf2d7419322eac79481e73cf03/','Пункт 5 части 1 статьи 7 ограничивает повторное требование уже заверенных электронных образов.',true),
('Государственные услуги — плата','Каково общее правило взимания платы за государственные и муниципальные услуги?','["Обязательный тариф органа по собственному усмотрению","Бесплатность, кроме предусмотренных законом случаев","Фиксированная плата за любое обращение","Плата только наличными в учреждении"]'::jsonb,1,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_103023/780c9842ff82f94d415db6b22a625ea65f69b662/','Часть 1 статьи 8 закрепляет бесплатность за исключением законных случаев.',true),
('Государственные услуги — плата','Кто определяет случаи, порядок и размеры государственной пошлины за предоставление услуги?','["Законодательство РФ о налогах и сборах","Любой работник принимающего учреждения","Регламент частного оператора сайта","Решение муниципального спортивного клуба"]'::jsonb,0,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_103023/780c9842ff82f94d415db6b22a625ea65f69b662/','Часть 2 статьи 8 связывает госпошлину с законодательством о налогах и сборах.',true),
('Государственные услуги — плата','МФЦ исправляет ошибку, допущенную его сотрудником в ранее выданном документе. Может ли он требовать плату за исправление?','["Да, во всех случаях повторной выдачи","Да, если документ бумажный","Да, по личному решению сотрудника","Нет, плата за исправление такой ошибки не взимается"]'::jsonb,3,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_103023/780c9842ff82f94d415db6b22a625ea65f69b662/','Часть 4 статьи 8 запрещает плату за исправление ошибок органа или МФЦ.',true),
('Государственные услуги — плата','Регион установил плату за услугу без законного основания. Какая правовая позиция следует из статьи 8?','["Платить обязаны все заявители независимо от закона","Любая региональная инструкция может заменить федеральное законодательство","Плата допустима лишь в предусмотренных законодательством случаях","Размер платы всегда определяет сотрудник на приёме"]'::jsonb,2,'Федеральный закон от 27.07.2010 № 210-ФЗ «Об организации предоставления государственных и муниципальных услуг»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_103023/780c9842ff82f94d415db6b22a625ea65f69b662/','Части 1–3 статьи 8 ограничивают платность государственно-муниципальных услуг.',true),
('Противодействие коррупции — уведомления','Представитель коммерческой организации предложил госслужащему вознаграждение за ускорение решения. Какая обязанность возникает?','["Принять деньги, чтобы установить личность плательщика","Уведомить представителя нанимателя, прокуратуру или иной госорган в установленном порядке","Сохранить разговор в тайне без действий","Обсудить только с другими участниками переговоров"]'::jsonb,1,'Федеральный закон от 25.12.2008 № 273-ФЗ «О противодействии коррупции»','статья 9','https://www.consultant.ru/document/cons_doc_LAW_82959/168ac76599fb643077ad0b13c4f2dc2c6126333a/','Часть 1 статьи 9 требует уведомлять о склонении к коррупционному правонарушению.',true),
('Противодействие коррупции — уведомления','Относится ли сообщение об обращении с целью склонения к коррупционному правонарушению к служебной обязанности?','["Да, за предусмотренным законом исключением для уже проверяемых фактов","Нет, это всегда сугубо личный выбор","Нет, касается только бывших служащих","Да, но исключительно после увольнения"]'::jsonb,0,'Федеральный закон от 25.12.2008 № 273-ФЗ «О противодействии коррупции»','статья 9','https://www.consultant.ru/document/cons_doc_LAW_82959/168ac76599fb643077ad0b13c4f2dc2c6126333a/','Часть 2 статьи 9 устанавливает служебную обязанность уведомления.',true),
('Противодействие коррупции — уведомления','Какие последствия допускает закон при неисполнении служащим обязанности уведомить о склонении к коррупции?','["Автоматическое повышение в должности","Исключительно устная благодарность","Никаких, если предложенная сумма мала","Увольнение со службы либо иная ответственность по законодательству"]'::jsonb,3,'Федеральный закон от 25.12.2008 № 273-ФЗ «О противодействии коррупции»','статья 9','https://www.consultant.ru/document/cons_doc_LAW_82959/168ac76599fb643077ad0b13c4f2dc2c6126333a/','Часть 3 статьи 9 предусматривает юридическую ответственность за нарушение обязанности уведомления.',true),
('Противодействие коррупции — уведомления','Кто определяет порядок регистрации уведомлений служащих об обращениях для склонения к коррупции?','["Любая частная бухгалтерская компания","Исключительно Центральная избирательная комиссия","Представитель нанимателя или работодатель","Случайно выбранный заявитель"]'::jsonb,2,'Федеральный закон от 25.12.2008 № 273-ФЗ «О противодействии коррупции»','статья 9','https://www.consultant.ru/document/cons_doc_LAW_82959/168ac76599fb643077ad0b13c4f2dc2c6126333a/','Часть 5 статьи 9 возлагает установление порядка на представителя нанимателя.',true),
('Противодействие коррупции — конфликт интересов','Для признания конфликта интересов обязательна уже выплаченная взятка?','["Да, необходим вступивший в силу приговор о взятке","Нет, достаточно влияния или возможности влияния личной заинтересованности","Да, только если денежное вознаграждение получено","Да, только при крупном имущественном ущербе"]'::jsonb,1,'Федеральный закон от 25.12.2008 № 273-ФЗ «О противодействии коррупции»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_82959/5d02242ebd04c398d2acf7c53dbc79659b85e8f3/','Статья 10 охватывает возможное влияние личной заинтересованности на объективность исполнения полномочий.',true),
('Противодействие коррупции — конфликт интересов','Руководитель принимает решение по контракту, в котором материально заинтересован супруг. Может ли возникнуть конфликт интересов?','["Да, заинтересованность близких лиц учитывается законом","Нет, учитывается исключительно доход должностного лица","Нет, семейные имущественные связи всегда исключены","Только после фактической выплаты вознаграждения"]'::jsonb,0,'Федеральный закон от 25.12.2008 № 273-ФЗ «О противодействии коррупции»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_82959/5d02242ebd04c398d2acf7c53dbc79659b85e8f3/','Часть 2 статьи 10 включает родственников и свойственников в оценку заинтересованности.',true),
('Противодействие коррупции — конфликт интересов','Ограничено ли понятие личной заинтересованности только получением денег?','["Да, только наличные средства","Да, только зарплату по службе","Да, только банковский перевод должностному лицу","Нет, оно включает имущество, права, услуги и другие преимущества"]'::jsonb,3,'Федеральный закон от 25.12.2008 № 273-ФЗ «О противодействии коррупции»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_82959/5d02242ebd04c398d2acf7c53dbc79659b85e8f3/','Часть 2 статьи 10 перечисляет широкий круг имущественных и иных выгод.',true),
('Противодействие коррупции — конфликт интересов','Может ли возникнуть конфликт интересов без непосредственного участия родственника, если служащий связан с компанией имущественными отношениями?','["Нет, учитываются только супруги","Нет, деловые связи никогда не могут создавать заинтересованность","Да, учитываются имущественные, корпоративные и иные близкие отношения","Только при нарушении налогового законодательства"]'::jsonb,2,'Федеральный закон от 25.12.2008 № 273-ФЗ «О противодействии коррупции»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_82959/5d02242ebd04c398d2acf7c53dbc79659b85e8f3/','Часть 2 статьи 10 распространяется и на определённые связи с гражданами и организациями.',true),
('Противодействие коррупции — урегулирование','Когда лицо обязано уведомить уполномоченное лицо о конфликте интересов или возможности его возникновения?','["Только по завершении контрактной процедуры","Как только ему стало об этом известно","После получения вознаграждения","Не раньше чем через год после назначения"]'::jsonb,1,'Федеральный закон от 25.12.2008 № 273-ФЗ «О противодействии коррупции»','статья 11','https://www.consultant.ru/document/cons_doc_LAW_82959/64ca591ea83268ee3d33f6e564cbcac0d3a073d9/','Часть 2 статьи 11 устанавливает уведомление при осведомлённости о конфликте.',true),
('Противодействие коррупции — урегулирование','Служащий обнаружил конфликт интересов, но полагает, что сам его контролирует. Может ли он не принимать никаких мер?','["Нет, обязан принимать меры к недопущению конфликта","Да, если лично уверен в объективности","Да, если сумма сделки несущественна","Да, если об этом не знает начальство"]'::jsonb,0,'Федеральный закон от 25.12.2008 № 273-ФЗ «О противодействии коррупции»','статья 11','https://www.consultant.ru/document/cons_doc_LAW_82959/64ca591ea83268ee3d33f6e564cbcac0d3a073d9/','Часть 1 статьи 11 закрепляет активную обязанность предотвратить конфликт.',true),
('Противодействие коррупции — урегулирование','Представителю нанимателя стало известно о личной заинтересованности сотрудника, способной вызвать конфликт. Что предписывает закон?','["Ожидать до окончания срока полномочий сотрудника","Игнорировать сведения, если нет письменной жалобы граждан","Немедленно согласовать сделку без проверки","Принять меры по предотвращению или урегулированию конфликта"]'::jsonb,3,'Федеральный закон от 25.12.2008 № 273-ФЗ «О противодействии коррупции»','статья 11','https://www.consultant.ru/document/cons_doc_LAW_82959/64ca591ea83268ee3d33f6e564cbcac0d3a073d9/','Часть 3 статьи 11 обязывает руководство реагировать.',true),
('Противодействие коррупции — урегулирование','Какой способ урегулирования конфликта интересов прямо предусмотрен статьёй 11?','["Автоматическое повышение оклада сотрудника","Назначение руководителя заинтересованной организации министром","Изменение служебного положения вплоть до отстранения в установленном порядке","Отмена бюджетной отчётности"]'::jsonb,2,'Федеральный закон от 25.12.2008 № 273-ФЗ «О противодействии коррупции»','статья 11','https://www.consultant.ru/document/cons_doc_LAW_82959/64ca591ea83268ee3d33f6e564cbcac0d3a073d9/','Часть 4 статьи 11 допускает изменение положения, отстранение и отказ от выгоды.',true),
('Противодействие коррупции — урегулирование','Может ли отвод или самоотвод применяться для предотвращения конфликта интересов?','["Нет, ни при каких обстоятельствах","Да, в предусмотренных законом случаях и порядке","Только по решению частной аудиторской фирмы","Исключительно при проведении выборов"]'::jsonb,1,'Федеральный закон от 25.12.2008 № 273-ФЗ «О противодействии коррупции»','статья 11','https://www.consultant.ru/document/cons_doc_LAW_82959/64ca591ea83268ee3d33f6e564cbcac0d3a073d9/','Часть 5 статьи 11 предусматривает отвод и самоотвод.',true),
('Противодействие коррупции — после службы','В течение какого периода после увольнения предусмотрены специальные ограничения для бывшего служащего при трудоустройстве в регулируемую им организацию по перечню должностей?','["В течение двух лет","Шесть месяцев","Пять лет","Без ограничения срока в любом случае"]'::jsonb,0,'Федеральный закон от 25.12.2008 № 273-ФЗ «О противодействии коррупции»','статья 12','https://www.consultant.ru/document/cons_doc_LAW_82959/e319cca703566186bfd83cacbeb23b217efc930e/','Часть 1 статьи 12 устанавливает двухлетний период.',true),
('Противодействие коррупции — после службы','Кто даёт согласие на трудоустройство бывшего служащего в регулируемую им организацию при наличии условий статьи 12?','["Избирательная комиссия по месту жительства","Любой бывший коллега","Исключительно финансовый директор новой организации","Соответствующая комиссия по служебному поведению и урегулированию конфликта интересов"]'::jsonb,3,'Федеральный закон от 25.12.2008 № 273-ФЗ «О противодействии коррупции»','статья 12','https://www.consultant.ru/document/cons_doc_LAW_82959/e319cca703566186bfd83cacbeb23b217efc930e/','Часть 1 статьи 12 требует согласия соответствующей комиссии.',true),
('Противодействие коррупции — после службы','Какова обязанность бывшего служащего из установленного перечня в течение двух лет при заключении подпадающего под статью 12 договора?','["Скрыть прежнюю должность от нового работодателя","Разместить копию договора в сети без обработки персональных данных","Сообщить работодателю сведения о последнем месте своей службы","Платить специальный налог в размере всей зарплаты"]'::jsonb,2,'Федеральный закон от 25.12.2008 № 273-ФЗ «О противодействии коррупции»','статья 12','https://www.consultant.ru/document/cons_doc_LAW_82959/e319cca703566186bfd83cacbeb23b217efc930e/','Часть 2 статьи 12 требует сообщать о последнем месте службы.',true)
